examples.source:
graph transformExample {
  transform result {
    value = ctx.value
  }
}

graph resourceExample {
  node lookup : httpResource {
    input {
      resourceId = ctx.resourceId
      params = {}
    }
  }
  transform result {
    payload = lookup.output.payload
  }
}

graph namedPortsExample {
  node lookup : httpResource {
    input {
      resourceId = ctx.resourceId
      params = {}
    }
  }
  transform result {
    payload = lookup.output.payload
  }
}

graph typedShapeExample {
  schema Profile {
    name: String
    note: String?
  }
  transform result {
    profile: Profile = { name: ctx.name, note: ctx.note }
    labels = [coalesce(ctx.label, "standard")]
  }
}

graph decisionExample {
  decision_table policy(score = ctx.score) hit=unique -> { decision: String } {
    rule (score: score >= 120) -> { decision: "accept" }
    otherwise -> { decision: "review" }
  }
}

graph boundaryExample {
  decision_table policy(score = ctx.score) hit=unique -> { decision: String } {
    rule (score: score < 120) -> { decision: "below" }
    rule (score: score == 120) -> { decision: "at" }
    rule (score: score > 120) -> { decision: "above" }
    otherwise -> { decision: "review" }
  }
}

graph cancelPolicyExample {
  node order : httpResource {
    input {
      resourceId = ctx.orderResourceId
      params = {}
    }
  }
  node liability : httpResource {
    input {
      resourceId = ctx.liabilityResourceId
      params = {}
    }
  }
  node cityPolicy : httpResource {
    input {
      resourceId = ctx.cityPolicyResourceId
      params = {}
    }
  }
  node history : httpResource {
    input {
      resourceId = ctx.historyResourceId
      params = {}
    }
  }
  decision_table policy(malicious = ctx.malicious, responsibility = ctx.responsibility) hit=unique -> { decision: String } {
    rule (malicious: malicious == true) -> { decision: "MANUAL_REVIEW" }
    rule (malicious: malicious == false, responsibility: responsibility == "DRIVER") -> { decision: "WAIVE_FULL" }
    otherwise -> { decision: "RETAIN" }
  }
  transform facts {
    orderPayload = order.output.payload
    liabilityPayload = liability.output.payload
    cityPolicyPayload = cityPolicy.output.payload
    historyPayload = history.output.payload
  }
}

graph designOnlyExample {
  node assess : "risk:eligibility" {
    input {
      score = ctx.score
      amount = ctx.amount
    }
  }
  transform result {
    eligible = assess.output.eligible
  }
}

responsibility.party:
  output: { type: { enum: [passenger, driver, platform, none] } }
  evaluationKind: API
  determinism: DETERMINISTIC
  inputs: { orderId: string }
  evaluationRef: ride-responsibility-service.decide#$.party

scn:cancel-dispute:
  inputs: [party, withinFree, abuse]
  hitPolicy: unique
  rules:
    - ruleId: R1
      when: { party: { eq: none }, withinFree: { eq: true }, abuse: { ne: confirmed } }
      outlet: { kind: INSTRUCTION, ref: 'ins:refund-waive-full', bind: { orderId: orderId, feeCharged: feeCharged } }
  otherwise: { kind: INSTRUCTION, ref: 'ins:escalate-human-ticket', bind: { orderId: orderId } }

ins:refund-waive-full:
  inputs: { orderId: string, feeCharged: number }
  output:
    result: { type: { fields: { decision: { enum: [WAIVED] }, waiveAmount: number } } }
    reasoning: required
  effect: WRITE
  writeGovernance: { downstreamSystem: refund-service, reconciliationKey: orderId, reconciliationAdapterRef: 'recon:refund-v1' }

sol:cancel-dispute:
  problem: Resolve a cancellation-fee dispute consistently.
  inputs: { party: responsibility.party, withinFree: cancel.withinFree, abuse: history.abuseSignal, orderId: dispute.orderSelected }
  scenarioTree: { root: 'scn:cancel-dispute' }
  instructions: ['ins:refund-waive-full', 'ins:uphold', 'ins:escalate-human-ticket']
  golden: 'caseSet:cancel-dispute'
